template <int KS, int NTT2, int NX>
__global__ void __launch_bounds__(256) e_kred(const float* __restrict__ P, const float* __restrict__ x, const float* __restrict__ b2p, float* __restrict__ out, int C, int HW, int M) {
  __shared__ float st[32 * 197];
  const int tid = threadIdx.x, cq = tid & 7, tl = tid >> 3;
  const int c0 = blockIdx.x * 32, b = blockIdx.y;
  const size_t base = ((size_t)b * C + c0) * HW;
  const int tot = 32 * HW, HP = HW + 1;
  float xv[NX], bv[NX];
#pragma unroll
  for (int i = 0; i < NX; i++) { const int j = tid + 256 * i; xv[i] = (j < tot) ? __ldg(x + base + j) : 0.f; bv[i] = (j < tot) ? __ldg(b2p + c0 + j / HW) : 0.f; }
