      pv[ks][i] = (t < HW) ? __ldg(reinterpret_cast<const float4*>(P + ((size_t)ks * M + (size_t)b * HW + t) * C + c0 + cq * 4)) : make_float4(0.f, 0.f, 0.f, 0.f); }
#pragma unroll
  for (int i = 0; i < NTT2; i++) { float4 a = pv[0][i];
#pragma unroll
    for (int ks = 1; ks < KS; ks++) { a.x += pv[ks][i].x; a.y += pv[ks][i].y; a.z += pv[ks][i].z; a.w += pv[ks][i].w; }
    const int t = tl + 32 * i;
    if (t < HW) { st[(cq * 4 + 0) * HP + t] = a.x; st[(cq * 4 + 1) * HP + t] = a.y; st[(cq * 4 + 2) * HP + t] = a.z; st[(cq * 4 + 3) * HP + t] = a.w; } }
  __syncthreads();
#pragma unroll
  for (int i = 0; i < NX; i++) { const int j = tid + 256 * i; if (j < tot) { const int c = j / HW, hw = j - c * HW; out[base + j] = xv[i] + bv[i] + st[c * HP + hw]; } }
}
